import os
def detect_virtualenv_path():
    """
    Detects the path to the virtual environment being used, if any.
    Works cross-platform (Windows/Linux/Mac).
    Returns:
        str: The absolute path to the virtual environment directory,
             or None if no virtual environment is detected.
    """
    # Check for VIRTUAL_ENV environment variable
    env_var = os.getenv('VIRTUAL_ENV')
    if env_var and os.path.isdir(env_var):
        return os.path.abspath(env_var)

    # Check for .venv directory in the current working directory or its parents
    current_dir = os.getcwd()
    while current_dir != os.path.dirname(current_dir):
        venv_path = os.path.join(current_dir, '.venv')
        if os.path.isdir(venv_path):
            return os.path.abspath(venv_path)
        current_dir = os.path.dirname(current_dir)

    # Check for virtualenvwrapper's WORKON_HOME and project directory
    workon_home = os.getenv('WORKON_HOME')
    if workon_home:
        project_name = os.path.basename(os.getcwd())
        venv_path = os.path.join(workon_home, project_name)
        if os.path.isdir(venv_path):
            return os.path.abspath(venv_path)

    # No virtual environment detected
    return None
if __name__ == '__main__':
    print(detect_virtualenv_path())",
    "mode": "overwrite"
  }
}
